/* ============================================================================
   RE:MK v36.3 – PHOTOREALISTIC FOOD VISUALS (27 ECHTFOTOS) & INDEXEDDB FOTO-UPLOAD
   - 3 randlose 3x3 WebP-Tafeln (27 fotorealistische Studio-Gerichtfotos, 100% offline)
   - Titel-zuerst & Veggie-/Vegan-sichere Zuordnung (0 Fehlzuordnungen!)
   - Unverzerrter Vollbild-Header (scharfer quadratischer Teller + Ambient-Blur)
   - Eigener Foto-Upload (Kamera/Galerie) pro Gericht -> Canvas WebP-Resize -> IndexedDB
   ============================================================================ */
(function initRemkFoodVisualsV363() {
  "use strict";
  if (window.REMK_FOOD_VISUALS && window.REMK_FOOD_VISUALS.version === "36.3") return;

  // Set 1 (Alltag & Fitness):
  // (0,0) Porridge/Skyr | (1,0) Strammer Max/Brot+Ei | (2,0) Hähnchen-Reis-Brokkoli
  // (0,1) Ofen-Lachs    | (1,1) Pasta Bolognese      | (2,1) Rindersteak & Kartoffeln
  // (0,2) Wraps/Tacos   | (1,2) Fitness-Salat        | (2,2) Schoko-Smoothie-Bowl
  const FOOD_SHEET_1 = "data:image/webp;base64,";

  // Set 2 (International & Familie):
  // (0,0) Tikka/Curry   | (1,0) Dal/Chana/Naan  | (2,0) Menemen/Shakshuka
  // (0,1) Köfte/Bulgur  | (1,1) Asia-Wok/Nudeln | (2,1) Lachs-Poke-Bowl
  // (0,2) Gyros/Griech. | (1,2) Ofen-Auflauf    | (2,2) Linsen-Eintopf/Chili
  const FOOD_SHEET_2 = "data:image/webp;base64,";

  // Set 3 (Alltag, Veggie, Süß & Snacks):
  // (0,0) Protein-Pancakes | (1,0) Gemüse-Omelett     | (2,0) Protein-Burger & Wedges
  // (0,1) Vegan Tofu-Bowl  | (1,1) Reiswaffel-Snack   | (2,1) Ofen-Kabeljau & Stampf
  // (0,2) Tortilla-Pizza   | (1,2) Ofen-Nuggets+Wedge | (2,2) Milchreis & Kirschen
  const FOOD_SHEET_3 = "data:image/webp;base64,";

  const IDB_NAME = "remk_v361_recipe_photos_db";
  const IDB_STORE = "photos";
  const _photoCache = Object.create(null);

  function normPhotoKey(title) {
    return String(title || "")
      .toLowerCase()
      .replace(/\([^)]*\)/g, " ")
      .replace(/[^a-z0-9äöüß]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 90);
  }

  function openPhotoDb() {
    return new Promise(function (resolve, reject) {
      try {
        if (!window.indexedDB) return reject(new Error("no idb"));
        const req = window.indexedDB.open(IDB_NAME, 1);
        req.onupgradeneeded = function (ev) {
          const db = ev.target.result;
          if (!db.objectStoreNames.contains(IDB_STORE)) {
            db.createObjectStore(IDB_STORE, { keyPath: "key" });
          }
        };
        req.onsuccess = function () { resolve(req.result); };
        req.onerror = function () { reject(req.error); };
      } catch (e) { reject(e); }
    });
  }

  function hydratePhotoCacheFromIdb() {
    openPhotoDb().then(function (db) {
      const tx = db.transaction(IDB_STORE, "readonly");
      const req = tx.objectStore(IDB_STORE).getAll();
      req.onsuccess = function () {
        const rows = req.result || [];
        rows.forEach(function (r) {
          if (r && r.key && r.dataUrl) _photoCache[r.key] = r.dataUrl;
        });
        if (rows.length > 0 && document.body.classList.contains("remk-v34-in-nutrition") && typeof window.renderV345NutritionCleanPanel === "function") {
          window.renderV345NutritionCleanPanel();
        }
      };
    }).catch(function () {});
  }

  function getCustomPhoto(title) {
    const k = normPhotoKey(title);
    return (k && _photoCache[k]) ? _photoCache[k] : null;
  }

  function saveCustomPhotoDataUrl(title, dataUrl) {
    const k = normPhotoKey(title);
    if (!k || !dataUrl) return Promise.resolve(false);
    _photoCache[k] = dataUrl;
    return openPhotoDb().then(function (db) {
      return new Promise(function (resolve) {
        const tx = db.transaction(IDB_STORE, "readwrite");
        tx.objectStore(IDB_STORE).put({ key: k, dataUrl: dataUrl, ts: Date.now() });
        tx.oncomplete = function () { resolve(true); };
        tx.onerror = function () { resolve(false); };
      });
    }).catch(function () { return true; });
  }

  function deleteCustomPhoto(title) {
    const k = normPhotoKey(title);
    if (!k) return Promise.resolve(false);
    delete _photoCache[k];
    return openPhotoDb().then(function (db) {
      return new Promise(function (resolve) {
        const tx = db.transaction(IDB_STORE, "readwrite");
        tx.objectStore(IDB_STORE).delete(k);
        tx.oncomplete = function () { resolve(true); };
        tx.onerror = function () { resolve(false); };
      });
    }).catch(function () { return true; });
  }

  function resizeImageFileToWebp(file) {
    return new Promise(function (resolve, reject) {
      const reader = new FileReader();
      reader.onload = function () {
        const img = new Image();
        img.onload = function () {
          const maxW = 720, maxH = 520;
          let w = img.width || 720, h = img.height || 520;
          const scale = Math.min(1, maxW / w, maxH / h);
          w = Math.max(120, Math.round(w * scale));
          h = Math.max(120, Math.round(h * scale));
          const cv = document.createElement("canvas");
          cv.width = w; cv.height = h;
          const ctx = cv.getContext("2d");
          ctx.drawImage(img, 0, 0, w, h);
          let out = "";
          try { out = cv.toDataURL("image/webp", 0.80); } catch (e) {}
          if (!out || !out.startsWith("data:image/webp")) {
            out = cv.toDataURL("image/jpeg", 0.80);
          }
          resolve(out);
        };
        img.onerror = reject;
        img.src = reader.result;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  function triggerCustomPhotoPicker(title, onUpdated) {
    const inp = document.createElement("input");
    inp.type = "file";
    inp.accept = "image/*";
    inp.style.display = "none";
    document.body.appendChild(inp);
    inp.onchange = function () {
      const file = inp.files && inp.files[0];
      try { inp.remove(); } catch (e) {}
      if (!file) return;
      resizeImageFileToWebp(file).then(function (dataUrl) {
        return saveCustomPhotoDataUrl(title, dataUrl).then(function () {
          if (typeof window.showV351Toast === "function") window.showV351Toast("📷 Eigenes Gericht-Foto gespeichert!");
          if (typeof onUpdated === "function") onUpdated(dataUrl);
        });
      }).catch(function () {
        if (typeof window.showV351Toast === "function") window.showV351Toast("⚠️ Foto konnte nicht verarbeitet werden");
      });
    };
    inp.click();
  }

  // v36.3: TITEL-ZUERST & VEGGIE-/VEGAN-SICHERE ZUORDNUNG ÜBER ALLE 27 ECHTFOTOS!
  function getFoodPhotoSpec(title, ingredientsText, cuisineHint, recipeType) {
    const t = String(title || "").toLowerCase();
    const rType = String(recipeType || "").toLowerCase();
    const isVeggie = (rType === "veggie" || rType === "vegan") || /\bvegan|\bveggie|vegetarisch|tofu|tempeh|seitan|lupine/.test(t);

    // 1. SNACKS (REIS-/MAISWAFFELN & DIPS) VOR WAFFELN/PANCAKES!
    if (/reiswaffel|maiswaffel|knäckebrot|knäcke|erdnussbutter.*banane|erdnussmus.*banane|guacamole-?hüttenkäse-?dip|büro-?box/.test(t)) {
      return { set: 3, col: 1, row: 1 };
    }
    // 2. SÜSSE GERICHTE, PANCAKES, MILCHREIS, SMOOTHIES, PORRIDGE (strikt mit Wortgrenze \blassi\b!)
    if (/pancake|pfannkuchen|\bwaffel\b|\bwaffeln\b|kaiserschmarrn|süße.*auflauf|grieß-?auflauf|quark-?grieß/.test(t)) {
      return { set: 3, col: 0, row: 0 };
    }
    if (/milchreis|cream-?of-?rice|grießbrei|kirsch|schwarzwälder|tiramisu|pudding(?!.*schoko)/.test(t)) {
      return { set: 3, col: 2, row: 2 };
    }
    if ((/smoothie|shake|schoko|kakao|brownie/.test(t)) && !/chili/.test(t)) {
      return { set: 1, col: 2, row: 2 };
    }
    if (/porridge|overnight|oats|hafer(?!flocken-?brot)|müsli|\blassi\b|beeren-?bowl|soja-?quark|skyr-?bowl|quark-?bowl|joghurt-?bowl/.test(t)) {
      return { set: 1, col: 0, row: 0 };
    }

    // 3. PIZZA / FLAMMKUCHEN / LAHMACUN
    if (/pizza|flammkuchen|lahmacun/.test(t)) return { set: 3, col: 0, row: 2 };

    // 4. BURGER / KÖFTE / BIFTEKI / CEVAPCICI / FRIKADELLEN
    if (/burger|cheeseburger|smash/.test(t)) return { set: 3, col: 2, row: 0 };
    if (/köfte|bifteki|cevapcici|frikadelle|köttbullar|geflügelbällchen/.test(t)) return { set: 2, col: 0, row: 1 };

    // 5. WRAPS / TACOS / DÜRÜM / FAJITA / QUESADILLA / ENCHILADA
    if (/wrap|dürüm|taco|fajita|quesadilla|rolle|enchilada/.test(t)) return { set: 1, col: 0, row: 2 };

    // 6. EIERGERICHTE, BROT, STULLE, VESPER, BAGEL, SANDWICH
    if (/menemen|shakshuka|huevos/.test(t)) return { set: 2, col: 2, row: 0 };
    if (/omelett|frittata|rührei|bauernfrühstück/.test(t)) return { set: 3, col: 1, row: 0 };
    if (/strammer max|stulle|vesper|doppeldecker|bagel|sandwich|vollkornbrot|bauernbrot|toast|brötchen|frühstücksteller|çılbır/.test(t)) {
      return { set: 1, col: 1, row: 0 };
    }

    // 7. SUPPEN, EINTÖPFE, CHILI, DAL, RAMEN
    if (/\bdal\b|\bdaal\b|chana masala|kichererbsen-?curry|palak paneer/.test(t)) return { set: 2, col: 1, row: 0 };
    if (/suppe|eintopf|chili|mercimek|gulasch/.test(t)) return { set: 2, col: 2, row: 2 };
    if (/ramen/.test(t)) return { set: 2, col: 1, row: 1 };

    // 8. INDISCH / CURRY / TANDOORI / BIRYANI
    if (/tikka|masala|butter-?chicken|curry|tandoori|biryani|keema/.test(t)) return { set: 2, col: 0, row: 0 };

    // 9. ASIATISCH (POKE vs. WOK/REISNUDELN)
    if (/poke|samurai.*lachs|lachs.*edamame|lachs.*teriyaki/.test(t)) return { set: 2, col: 2, row: 1 };
    if (/wok|teriyaki|asia|reisnudel|glasnudel|thai|bulgogi|süß-?sauer|fried rice|bún|edamame-?sesam/.test(t)) {
      return { set: 2, col: 1, row: 1 };
    }

    // 10. PASTA / NUDELN / GNOCCHI / SPÄTZLE / LASAGNE / TORTELLINI
    if (/pasta|spaghetti|penne|nudel|gnocchi|spätzle|lasagne|bolognese|tortellini|\bmac\b/.test(t)) {
      return { set: 1, col: 1, row: 1 };
    }

    // 11. FISCH & MEERESFRÜCHTE (Lachs vs. Kabeljau/Weißfisch/Thunfisch)
    if (/lachs/.test(t)) return { set: 1, col: 0, row: 1 };
    if (/kabeljau|seelachs|fischstäbchen|forelle|matjes|fisch/.test(t)) return { set: 3, col: 2, row: 1 };
    if (/thunfisch/.test(t)) return /salat|bowl/.test(t) ? { set: 1, col: 1, row: 2 } : { set: 3, col: 2, row: 1 };
    if (/garnele|gambas|paella/.test(t)) return { set: 2, col: 0, row: 2 };

    // 12. GRIECHISCH / MEDITERRAN / GYROS / DÖNER / FALAFEL
    if (/gyros|tzatziki|griech|feta|caprese|tavuk|döner/.test(t)) return { set: 2, col: 0, row: 2 };
    if (/falafel|kısır|kisir|karnıyarık|burrito-?bowl/.test(t)) return { set: 2, col: 0, row: 1 };

    // 13. HAUPT-SALATE (nicht bloß "mit Salat" als Beilage)
    if (/salat(?!gurke)/.test(t) && !/(?:&|und|mit)[^,]*salat$/.test(t)) return { set: 1, col: 1, row: 2 };

    // 14. VEGANE / VEGETARISCHE PROTEIN-BOWLS & PFANNEN (NIEMALS Fleischfoto!)
    if (isVeggie || /tofu|tempeh|seitan|lupine|buchweizen|quinoa|kichererbse|beluga-?linsen|edamame|bergkäse/.test(t)) {
      return { set: 3, col: 0, row: 1 };
    }

    // 15. HÄHNCHEN / PUTE (Nuggets/Kartoffeln vs. Ofen-Auflauf vs. Klassisch Reis+Brokkoli)
    if (/nugget|wedges|geschnetzelte|bratkartoffel|kartoffel|rosmarinkartoffel|süßkartoffel|stampf/.test(t) && /hähnchen|pute|geflügel/.test(t)) {
      return { set: 3, col: 1, row: 2 };
    }
    if (/ofen|blech|traybake|auflauf/.test(t) && /hähnchen|pute|geflügel/.test(t)) {
      return { set: 2, col: 1, row: 2 };
    }
    if (/hähnchen|pute|chicken|geflügel/.test(t)) return { set: 1, col: 2, row: 0 };

    // 16. RIND / STEAK / HACK / SCHWEIN / KASSELER
    if (/steak|rumpsteak|rind|tatar|hack|schwein|kasseler|filet|schnitzel|braten/.test(t)) {
      return { set: 1, col: 2, row: 1 };
    }

    // Fallback nur bei völlig unspezifischen eigenen Rezepten über Zutaten:
    const ing = String(ingredientsText || "").toLowerCase();
    if (/haferflocken|skyr|quark/.test(ing) && !/hähnchen|pute|rind|lachs|hack/.test(ing)) return { set: 1, col: 0, row: 0 };
    if (/tofu|tempeh|linsen|kichererbsen/.test(ing)) return { set: 3, col: 0, row: 1 };
    return { set: 1, col: 2, row: 0 };
  }

  function getSheetBySet(setNum) {
    if (setNum === 3) return FOOD_SHEET_3;
    if (setNum === 2) return FOOD_SHEET_2;
    return FOOD_SHEET_1;
  }

  function renderFoodThumbHtml(title, ingredientsText, cuisineHint, sizePx, recipeType) {
    const sz = sizePx || 64;
    const custom = getCustomPhoto(title);
    if (custom) {
      return `<div class="v361-food-thumb" style="width:${sz}px;height:${sz}px;border-radius:14px;overflow:hidden;flex-shrink:0;background:#1a202c;border:1px solid var(--v34-border);"><img src="${custom}" alt="Gericht" style="width:100%;height:100%;object-fit:cover;display:block;"/></div>`;
    }
    const spec = getFoodPhotoSpec(title, ingredientsText, cuisineHint, recipeType);
    const sheet = getSheetBySet(spec.set);
    const bx = spec.col === 0 ? "0%" : (spec.col === 1 ? "50%" : "100%");
    const by = spec.row === 0 ? "0%" : (spec.row === 1 ? "50%" : "100%");
    return `<div class="v361-food-thumb" style="width:${sz}px;height:${sz}px;border-radius:14px;overflow:hidden;flex-shrink:0;background:#1a202c;border:1px solid var(--v34-border);"><span style="display:block;width:100%;height:100%;background-image:url('${sheet}');background-size:300% 300%;background-position:${bx} ${by};background-repeat:no-repeat;"></span></div>`;
  }

  // Unverzerrter Vollbild-Hero: Ambient-Blur-Hintergrund + gestochen scharfer 1:1-Teller im Zentrum!
  function renderFoodHeroInnerHtml(title, ingredientsText, cuisineHint, recipeType) {
    const custom = getCustomPhoto(title);
    if (custom) {
      return `<img src="${custom}" alt="Gericht-Foto" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;"/><div style="position:absolute;inset:0;background:linear-gradient(180deg,rgba(2,6,23,0.42) 0%,rgba(2,6,23,0.10) 55%,rgba(2,6,23,0.58) 100%);"></div>`;
    }
    const spec = getFoodPhotoSpec(title, ingredientsText, cuisineHint, recipeType);
    const sheet = getSheetBySet(spec.set);
    const bx = spec.col === 0 ? "0%" : (spec.col === 1 ? "50%" : "100%");
    const by = spec.row === 0 ? "0%" : (spec.row === 1 ? "50%" : "100%");
    return `
      <div style="position:absolute;inset:-24px;background-image:url('${sheet}');background-size:300% 300%;background-position:${bx} ${by};background-repeat:no-repeat;filter:blur(18px) brightness(0.45);transform:scale(1.12);"></div>
      <div style="position:relative;z-index:2;width:194px;height:194px;border-radius:22px;overflow:hidden;box-shadow:0 14px 36px rgba(0,0,0,0.52);border:2px solid rgba(255,255,255,0.18);background:#1a202c;flex-shrink:0;">
        <span style="display:block;width:100%;height:100%;background-image:url('${sheet}');background-size:300% 300%;background-position:${bx} ${by};background-repeat:no-repeat;"></span>
      </div>
    `;
  }

  window.REMK_FOOD_VISUALS = {
    version: "36.3",
    getFoodPhotoSpec: getFoodPhotoSpec,
    getCustomPhoto: getCustomPhoto,
    saveCustomPhotoDataUrl: saveCustomPhotoDataUrl,
    deleteCustomPhoto: deleteCustomPhoto,
    triggerCustomPhotoPicker: triggerCustomPhotoPicker,
    renderFoodThumbHtml: renderFoodThumbHtml,
    renderFoodHeroInnerHtml: renderFoodHeroInnerHtml
  };

  hydratePhotoCacheFromIdb();
})();
